// ── QUALITY ───────────────────────────────────────────
function renderQuality() {
  const ops = DATA.operators;
  const avg = ops.length ? Math.round(ops.reduce((s,o)=>s+o.reliability_score,0)/ops.length) : 0;
  const counts = { A:0, B:0, C:0, D:0 };
  ops.forEach(o => counts[o.reliability_level]=(counts[o.reliability_level]||0)+1);

  document.getElementById('quality-kpi').innerHTML = [
    { label: 'Score moyen',   value: avg + '%',  sub: 'Tous opérateurs' },
    { label: 'Niveau A ≥90', value: counts.A,    sub: 'Très fiable' },
    { label: 'Niveau B 70–89',value: counts.B,   sub: 'Fiable' },
  ].map(k=>`<div class="kpi"><div class="kpi-label">${k.label}</div><div class="kpi-value">${k.value}</div><div class="kpi-sub">${k.sub}</div></div>`).join('');

  const colors = { A:'#2db36a', B:'#e8b84b', C:'#f5a623', D:'#e07f8a' };
  const total = ops.length;
  document.getElementById('quality-bar').innerHTML = ['A','B','C','D'].filter(l=>counts[l]).map(l=>
    `<div class="quality-segment" style="flex:${counts[l]};background:${colors[l]}" title="${l}: ${counts[l]}"></div>`).join('');
  document.getElementById('quality-legend').innerHTML = ['A','B','C','D'].map(l=>
    `<span><span class="q-dot" style="background:${colors[l]}"></span>Niveau ${l}: ${counts[l]||0}</span>`).join('');

  document.getElementById('quality-body').innerHTML = [...ops].sort((a,b)=>b.reliability_score-a.reliability_score).map(o=>
    `<tr><td><strong>${o.operator_name}</strong></td><td>${o.country_name_fr}</td><td>${scoreBar(o.reliability_score,o.reliability_level)}</td><td>${badge(o.reliability_level)}</td><td style="font-size:11px;color:var(--muted)">${o.source_type||'—'}</td></tr>`
  ).join('');
}

// ── GLOBAL SEARCH ─────────────────────────────────────
function globalSearch(q) {
  if (!q || q.length < 2) {
    if (currentPage === 'search') nav('dashboard', document.querySelector('.nav-item'));
    return;
  }
  const ql = q.toLowerCase();
  const ops   = DATA.operators.filter(o=>[o.operator_name,o.sector,o.products_services,o.hs_codes,o.city].some(v=>v&&v.toLowerCase().includes(ql)));
  const insts = DATA.institutions.filter(i=>[i.name,i.type,i.city].some(v=>v&&v.toLowerCase().includes(ql)));
  const facs  = DATA.facilitators.filter(f=>[f.actor_name,f.actor_type,f.services].some(v=>v&&v.toLowerCase().includes(ql)));
  const total = ops.length + insts.length + facs.length;
  document.getElementById('search-summary').innerHTML = `<strong>${total}</strong> résultat${total!==1?'s':''} pour "<strong>${q}</strong>"`;
  let html = '';
  if (ops.length) html += `<div class="section-title">Opérateurs (${ops.length})</div><div class="table-wrap"><table><thead><tr><th>Pays</th><th>Opérateur</th><th>Secteur</th><th>Produits</th><th>Fiabilité</th></tr></thead><tbody>${ops.map(o=>`<tr><td>${o.iso3}</td><td><strong>${o.operator_name}</strong></td><td><span class="tag">${o.sector}</span></td><td style="font-size:11px;color:var(--muted)">${(o.products_services||'').substring(0,40)}</td><td>${badge(o.reliability_level)}</td></tr>`).join('')}</tbody></table></div>`;
  if (insts.length) html += `<div class="section-title">Institutions (${insts.length})</div><div class="table-wrap"><table><thead><tr><th>Pays</th><th>Institution</th><th>Type</th><th>Fiabilité</th></tr></thead><tbody>${insts.map(i=>`<tr><td>${i.iso3}</td><td><strong>${i.name}</strong></td><td><span class="tag">${i.type}</span></td><td>${badge(i.reliability_level)}</td></tr>`).join('')}</tbody></table></div>`;
  if (facs.length) html += `<div class="section-title">Facilitateurs (${facs.length})</div><div class="table-wrap"><table><thead><tr><th>Pays</th><th>Acteur</th><th>Type</th><th>Fiabilité</th></tr></thead><tbody>${facs.map(f=>`<tr><td>${f.iso3}</td><td><strong>${f.actor_name}</strong></td><td><span class="tag">${f.actor_type}</span></td><td>${badge(f.reliability_level)}</td></tr>`).join('')}</tbody></table></div>`;
  if (!html) html = '<div class="empty">Aucun résultat trouvé.</div>';
  document.getElementById('search-results').innerHTML = html;
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
  document.getElementById('page-search').classList.add('active');
  document.getElementById('page-title').textContent = PAGES['search'];
}

// ── EXPORT CSV ────────────────────────────────────────
// Réservé à l'administrateur (demande du 06/11/2026) : les boutons, masqués
// dans la page, n'apparaissent que si la session a le format CSV
// (`export_formats` de GET /api/auth/me, sans « csv » pour toutes les formules).
let exportCsvAutorise = false;

async function verifierDroitExport() {
  try {
    const res = await fetch('/api/auth/me', { credentials: 'include' });
    const me = res.ok ? await res.json() : null;
    exportCsvAutorise = Boolean(me && Array.isArray(me.export_formats) && me.export_formats.includes('csv'));
  } catch (e) {
    exportCsvAutorise = false;
  }
  document.querySelectorAll('[data-export]').forEach((b) => { b.hidden = !exportCsvAutorise; });
}

function exportCSV(type) {
  const data = type==='operators' ? DATA.operators : type==='institutions' ? DATA.institutions : DATA.facilitators;
  if (!data.length) return;
  const cols = Object.keys(data[0]);
  const csv = [cols.join(','), ...data.map(r=>cols.map(c=>`"${(r[c]||'').toString().replace(/"/g,'""')}"`).join(','))].join('\n');
  const a = document.createElement('a');
  a.href = 'data:text/csv;charset=utf-8,\uFEFF' + encodeURIComponent(csv);
  a.download = `afcfta_${type}_${new Date().toISOString().slice(0,10)}.csv`;
  a.click();
}

// ── INIT FILTERS ──────────────────────────────────────
function initFilters() {
  const uniqueCountries = [...new Map((DATA.countries || []).map(c=>[c.iso3,{iso3:c.iso3,name:c.name_fr||c.name_en||c.iso3}])).values()];
  ['op-country','inst-country','fac-country'].forEach(id => {
    const sel = document.getElementById(id);
    if (!sel) return;
    sel.innerHTML = '<option value="">Tous les pays</option>';
    uniqueCountries.sort((a,b)=>a.name.localeCompare(b.name)).forEach(c => {
      sel.innerHTML += `<option value="${c.iso3}">${c.name}</option>`;
    });
  });
  const uniqueSectors = [...new Set(DATA.operators.map(o=>o.sector))].sort();
  const opSec = document.getElementById('op-sector');
  opSec.innerHTML = '<option value="">Tous les secteurs</option>';
  uniqueSectors.forEach(s => opSec.innerHTML += `<option value="${s}">${s.substring(0,36)}</option>`);
}

// ── BOOT ─────────────────────────────────────────────
async function bootAtlas() {
  await loadValidatedPack();
  applyValidationPolicy();
  recomputeCountryCounts();
  refreshStatsFromData();
  initFilters();
  renderDashboard();
  renderCountries();
  renderOperators();
  renderInstitutions();
  renderFacilitators();
}

// Événements déclarés par des attributs data-* et des écouteurs, au lieu de
// gestionnaires onclick="…" : la CSP de la page n'autorise aucun script inline
// (audit INFO-3).
function brancherEvenements() {
  document.addEventListener('click', function (e) {
    const navEl = e.target.closest('[data-nav]');
    if (navEl) {
      nav(navEl.dataset.nav, navEl.hasAttribute('data-nav-retour') ? null : navEl);
      return;
    }
    const exportEl = e.target.closest('[data-export]');
    if (exportEl) {
      if (exportCsvAutorise) exportCSV(exportEl.dataset.export);
      return;
    }
    const carte = e.target.closest('#country-grid [data-iso3]');
    if (carte) showCountryDetail(carte.dataset.iso3);
  });
  const ecouter = (id, evenement, fn) => document.getElementById(id).addEventListener(evenement, fn);
  ecouter('gsearch', 'input', (e) => globalSearch(e.target.value));
  ecouter('region-filter', 'change', renderCountries);
  ecouter('op-q', 'input', renderOperators);
  ['op-country', 'op-sector', 'op-level'].forEach((id) => ecouter(id, 'change', renderOperators));
  ['inst-country', 'inst-type'].forEach((id) => ecouter(id, 'change', renderInstitutions));
  ['fac-country', 'fac-type'].forEach((id) => ecouter(id, 'change', renderFacilitators));
}

brancherEvenements();
verifierDroitExport();
bootAtlas();
